import os
import json
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _polygon_to_bbox(polygon: Any) -> Optional[Dict[str, float]]:
    if not polygon:
        return None
    try:
        points = []
        for p in polygon:
            if isinstance(p, dict):
                x = float(p.get("x", 0.0))
                y = float(p.get("y", 0.0))
            else:
                x = float(getattr(p, "x"))
                y = float(getattr(p, "y"))
            points.append((x, y))
        if not points:
            return None
        xs = [p[0] for p in points]
        ys = [p[1] for p in points]
        return {"x0": min(xs), "y0": min(ys), "x1": max(xs), "y1": max(ys)}
    except Exception:
        return None


def _as_text(field: Any) -> str:
    if field is None:
        return ""
    if isinstance(field, str):
        return field
    value = getattr(field, "content", None)
    if value is not None:
        return value
    try:
        return str(field)
    except Exception:
        return ""


def extract_table_cells_and_rows(
    document_path: str,
    model_id: str = "prebuilt-layout",
    endpoint: Optional[str] = None,
    key: Optional[str] = None,
) -> Dict[str, Any]:
    endpoint = endpoint or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = key or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")
    if not endpoint or not key:
        raise ValueError(
            "Azure Document Intelligence credentials are required via "
            "AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY."
        )

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(model_id=model_id, body=f)
    result = poller.result()

    extracted_tables: List[Dict[str, Any]] = []

    for table_index, table in enumerate(getattr(result, "tables", []) or []):
        cells_out: List[Dict[str, Any]] = []
        row_map: Dict[int, Dict[str, Any]] = {}

        for cell in getattr(table, "cells", []) or []:
            row_index = int(getattr(cell, "row_index", 0))
            col_index = int(getattr(cell, "column_index", 0))
            row_span = int(getattr(cell, "row_span", 1) or 1)
            col_span = int(getattr(cell, "column_span", 1) or 1)
            content = _as_text(getattr(cell, "content", ""))

            bbox = _polygon_to_bbox(getattr(cell, "polygon", None) or getattr(cell, "bounding_regions", None))

            cell_obj = {
                "row_index": row_index,
                "column_index": col_index,
                "row_span": row_span,
                "column_span": col_span,
                "content": content,
                "kind": getattr(cell, "kind", None),
                "bounding_box": bbox,
            }
            cells_out.append(cell_obj)

            row = row_map.setdefault(
                row_index,
                {"row_index": row_index, "cells": [], "texts": [], "column_indices": []},
            )
            row["cells"].append(cell_obj)
            row["texts"].append(content)
            row["column_indices"].append(col_index)

        rows_out = []
        for row_index in sorted(row_map.keys()):
            row = row_map[row_index]
            ordered_cells = sorted(row["cells"], key=lambda c: (c["column_index"], c["row_index"]))
            rows_out.append(
                {
                    "row_index": row_index,
                    "cells": ordered_cells,
                    "text": "\t".join(c.get("content", "") for c in ordered_cells),
                }
            )

        extracted_tables.append(
            {
                "table_index": table_index,
                "row_count": int(getattr(table, "row_count", len(rows_out)) or len(rows_out)),
                "column_count": int(getattr(table, "column_count", 0) or 0),
                "cells": sorted(cells_out, key=lambda c: (c["row_index"], c["column_index"])),
                "rows": rows_out,
            }
        )

    return {
        "document_metadata": {
            "model_id": model_id,
            "page_count": len(getattr(result, "pages", []) or []),
        },
        "tables": extracted_tables,
        "raw_result": result.to_dict() if hasattr(result, "to_dict") else json.loads(json.dumps(result, default=str)),
    }
